CREATE OR REPLACE FUNCTION ECAMS.BASE_SAMECHECK
(ITEMID IN VARCHAR2,BASEITEM IN VARCHAR2,RSRCCD IN VARCHAR2)
RETURN VARCHAR2
IS
   VCNT1 INT := 0;
 --- 자신의 기준프로그램이 동시적용여부 CHECK
 -- 사용안함 (2018/08/21)
BEGIN
    IF ITEMID = BASEITEM THEN
       RETURN 'Y';
    END IF;
    SELECT  COUNT(*)
      INTO  VCNT1
      FROM  CMR0020
     WHERE  CR_ITEMID=BASEITEM
       AND  CR_ECLRSRC='96'
       AND  CR_RSRCCD=RSRCCD;

     IF VCNT1 > 0 THEN
        RETURN 'N';
     ELSE RETURN 'Y';
     END IF;
end;